function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 50) return 'nums needs 2 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000000 || v > 100000000)) return 'Each value of nums is an integer from -10^8 to 10^8.';
  if (!Number.isInteger(k) || k < 2 || k > nums.length) return 'k is an integer from 2 to nums.length.';
  return null;
}

