function sumOfPowers(nums, k) {
  const MOD = 1000000007n;
  const n = nums.length;
  nums.sort((a, b) => a - b);
  const differences = new Set();
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      differences.add(nums[j] - nums[i]);
    }
  }
  const thresholds = [...differences].sort((a, b) => a - b);

  const countAtLeast = (d) => {
    let ways = new Array(n).fill(1);
    for (let len = 2; len <= k; len++) {
      const next = new Array(n).fill(0);
      let reachable = 0;
      let left = 0;
      for (let j = 0; j < n; j++) {
        while (left < j && nums[j] - nums[left] >= d) {
          reachable += ways[left];
          left++;
        }
        next[j] = reachable;
      }
      ways = next;
    }
    return ways.reduce((sum, w) => sum + w, 0);
  };

  let total = 0n;
  let previous = 0;
  for (const d of thresholds) {
    const count = countAtLeast(d);
    if (count === 0) break;
    total = (total + BigInt(d - previous) * BigInt(count)) % MOD;
    previous = d;
  }
  return Number(total);
}

