function sumOfPowers(nums, k) {
  // List every choice of k positions and measure all pairs directly.
  let total = 0;
  const chosen = [];
  const visit = (start) => {
    if (chosen.length === k) {
      let least = Infinity;
      for (let a = 0; a < k; a++) {
        for (let b = a + 1; b < k; b++) least = Math.min(least, Math.abs(chosen[a] - chosen[b]));
      }
      total = (total + least) % 1000000007;
      return;
    }
    for (let i = start; i <= nums.length - (k - chosen.length); i++) {
      chosen.push(nums[i]);
      visit(i + 1);
      chosen.pop();
    }
  };
  visit(0);
  return total;
}

