function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 50 : int(2, 9);
  const k = large ? [2, 3, int(4, 12), int(13, 49), 50][int(0, 4)] : int(2, n);
  const mode = int(0, 3);
  let nums;
  if (mode === 0) {
    // Wide random values.
    nums = Array.from({ length: n }, () => int(-100000000, 100000000));
  } else if (mode === 1) {
    // A narrow range, so many values repeat.
    nums = Array.from({ length: n }, () => int(-6, 6));
  } else if (mode === 2) {
    // Powers of two on both sides of zero: gaps of very different sizes.
    nums = Array.from({ length: n }, () => (rand() < 0.5 ? -1 : 1) * 2 ** int(0, 26));
  } else {
    // A shuffled, slightly jittered arithmetic progression.
    const step = int(1, large ? 4000000 : 10);
    const start = int(-100000000, 100000000 - step * (n - 1) - 1);
    nums = Array.from({ length: n }, (_, i) => start + step * i + int(0, 1));
    for (let i = n - 1; i > 0; i--) {
      const j = int(0, i);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums, k];
}
